INSERT INTO claim_issues VALUES(1,'AVL','AVL 빌드업 스타일: Balanced·Counter·Short','26/27 시즌 정본 빌드업 스타일을 Balanced 유지할지, Counter(또는 Short Passing)로 바꿀지 판정한다.','PL 경기별 점유율(matches.possession)·롱패스 비율·GK 롱킥 비중·시퀀스당 패스를 홈/원정 각 3경기 이상으로 나눠 상대 압박 강도와 함께 본다(#356). 25/26 대비 일관되게 높으면 Counter 검토(#196), 브뤼헤(승)·포레스트(패) 파이널 서드 진입·박스 진입 대조(#45·#52), 브렌트퍼드·뉴캐슬 롱패스 비율 vs 시즌 평균(#273·#298), 역습 슈팅 비율 25/26 대비(#294). 토트넘전(롱볼 14.5%)은 상대 맞춤 1경기로 분리.','matches',6,'league',NULL,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(2,'AVL','상대 유형별 경기 프리셋 후보(백3·투톱·대인압박·고라인)','상대 포메이션·압박 유형에 따른 빌드업 변주를 경기 전용 설정(match_game_setups) 또는 게임플랜 B안으로 기록할지 판정한다.','26/27 공식전을 상대 유형(백3 / 투톱 / 대인 고압박 / 고라인)으로 분류해 유형별 2경기 이상에서: 파이널 서드 진입·측면 대 중앙 비율(백3, #56), CB 자원의 DM 슬롯 선발 여부(투톱, #370), GK·CB 롱패스 비중·자기 진영 소유 상실 vs 25/26 첼시전(대인압박, #372), 경기 중 형태 전환 match_tactical_changes(#373), 반별 롱패스 비중 match_period_stats(고라인, #377·#199). 유형별 표본 2경기 미만이면 그 유형만 이월.','matches',5,'official',NULL,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(3,'AVL','스즈키 GK 역할·배급: ballplaying vs sweeper','스즈키의 GK 역할(gk_ballplaying/Build-Up 유지 여부)과 배급 방식(지연 후 롱볼·압박 억제)을 판정한다.','스즈키 선발 경기의 패스 성공률·롱패스 비율·박스 밖 전진 빈도(#281·#324), 롱패스 목표 지점(9번 쪽)과 상대 PPDA(#282), 골킥 시 CB 벌림 형태(#283 — 영상 필요), Opta Claim/KeeperPickup→다음 Pass 간격과 Longball 비율 2경기 이상(#198 — Opta 이벤트 필요).','player_starts',3,'official',132,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(4,'AVL','잭슨 ST 역할: 어드밴스드 vs 폴스9(배후 러너)','만잠비·음바예 복귀 후 잭슨이 st_advanced(Support/Attack)인지 st_false9인지, 잭슨 하강 시 2선 배후 침투가 생기는지 판정한다.','만잠비 또는 음바예가 선발한 PL 경기만 센다. 잭슨 하강 빈도 분포(obs#505)·단일 경기 커널 1위(st_advanced vs st_false9)와, 잭슨 하강 장면의 2선 배후 침투 빈도(#392·#394·#398)를 5경기 누적으로 본다.','matches',5,'league',NULL,NULL,NULL,'2026-10-21',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(5,'AVL','잭슨 ST 포커스·변형: 왓킨스 대비 측면·박스·홀드업','잭슨의 포커스(Support vs Attack)와 변형(st_target 홀드업 여부), ST 고립 여부를 25/26 왓킨스 대비로 판정한다.','잭슨 26/27 공식전 측면 셀·하프라인 셀·박스 안 터치 비중을 25/26 왓킨스와 대조(#333 계열 8건), 뉴캐슬전 등지고 받기·공중 경합·소유 상실·파울 획득으로 st_target 근거 확인(#300·#310·#313·#314), 잭슨–최근접 동료(CAM·LM·RM) 거리를 25/26 왓킨스–로저스와 PL 3경기 이상 비교(#465), 포커스 Versatile→Support 변경은 사용자 확인(#247). 이미 판정 가능.','player_starts',3,'official',76,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(6,'AVL','RM 인선: 침투형 윙어 vs 맥긴 체제','음바예(또는 침투형 윙어)가 RM 주전 슬롯을 차지할 때 RM wm_winger/Attack 정본과 잭슨 너머 침투·캐시 깊이가 어떻게 달라지는지 판정한다.','음바예 RM/RAM 선발 경기 3경기 vs 맥긴 RAM 선발 경기 3경기: 잭슨 박스 터치·팀 뒷공간 패스 수(#355·#421·#425), 캐시 평균 깊이(#416), 상대 풀백 전진 히트맵(#272). 음바예 RM 3경기 도달 시 wm_winger/Attack 유지 판정(#346·#347), 맥긴 체제 지속 시 avl-mcginn-inside로 넘긴다.','player_starts',3,'official',86,'RM,RAM,RW',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(7,'AVL','음바예 역할: 터치라인 윙어 vs 인사이드 포워드','음바예의 역할을 wm_winger와 wm_insidefwd 중 무엇으로 둘지 판정한다.','음바예 선발 3경기 이상 단일 경기 fit(prescriptions/커널)에서 wm_winger와 wm_insidefwd 차이가 0.05를 넘는지. 교체 표본(#214, 26′)은 제외. 좌·우 배치(RAM/LAM)별로 나눠 본다.','player_starts',3,'official',86,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(8,'AVL','맥긴 RM: 터치라인 윙어 vs 안쪽형','맥긴 RM 체제에서 RM 역할을 wm_winger/Attack로 둘지 안쪽형으로 재검토할지, 그 안쪽 이동의 우측 rest-defense 비용을 판정한다.','맥긴 RAM 선발 경기의 점유 국면 map25_poss 평균 avg_y(25~75 안이면 안쪽형 후보, #369), 뉴캐슬전 46′ 이후 맥긴 위치·크로스·박스 진입(#302), 맥긴 안쪽 이동 시 상대 좌측 윙어의 공격 비중(#250). 이미 판정 가능(맥긴 RAM 10선발).','player_starts',3,'official',10,'RM,RAM,RW',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(9,'AVL','가르나초 LM 기용 시 좌측 구조','가르나초가 LM으로 선발할 때 터치라인 폭·마첸 안쪽 이동(좌우 반전)·복귀 수비가 실제로 나타나는지 판정한다.','가르나초 LM/LAM 선발 경기: 가르나초 avg_y·히트맵 폭(#203), LM 단일 fit wm_winger 쪽 여부·LB 평균 위치가 RB보다 낮은지(#458), 마첸(LB) map25_poss 중앙 셀 비중 상승(#351·#419), 45분+ 경기의 비점유 전진도·태클·인터셉트(#460, 음바예 #114 기준).','player_starts',3,'official',58,'LM,LAM,LW',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(10,'AVL','윙어 드리블·폭 재량','빌라 윙어에게 1대1 돌파·크로스·터치라인 폭 재량이 주어지는지 판정한다.','가르나초·음바예·알리송이 선발한 PL 경기만 본다. 드리블 시도/90·크로스 수를 25/26 측면 자원과 대조(#286·#409·#429), 터치라인 셀(열0·열4) 비중(#399).','matches',5,'league',NULL,NULL,NULL,'2026-10-21',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(11,'AVL','루헤리 LB 역할: 공격형 윙백 vs 수비형 풀백','루헤리 LB 기용 시 fb_att_wb/Support가 맞는지(vs fb_fullback/Defend) 판정한다.','루헤리 LB 선발 5경기: 단일 경기 커널 1위(#454는 2경기로 판정 가능), 그리드·전진 깊이를 마첸과 대조(#352), 수비·전진 지표 추세(#277).','player_starts',5,'official',78,'LB',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(12,'AVL','루헤리 크로스 위치: 이른 크로스 vs 컷백','루헤리의 크로스·키패스 시작 위치가 하프스페이스 이른 크로스형인지 바이라인·컷백형인지 판정한다.','루헤리 빌라 공식전 선발 2경기 이상의 크로스·키패스 시작 좌표 분포(하프스페이스 vs 바이라인)를 마첸과 대조(#284·#453). 이미 판정 가능(LB 3선발) — 단 크로스 좌표 이벤트 수집 필요.','player_starts',2,'official',78,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(13,'AVL','풀백 비대칭: 한쪽 전진·반대쪽 백3','빌라가 한쪽 풀백 전진·반대쪽 좁힘의 비대칭 백3를 쓰는지, RB 정본(fb_wingback/Balanced vs fb_att_wb)과 좌측 커버 공백을 판정한다.','캐시 RB 선발 경기의 단일 fit(fb_wingback vs fb_att_wb, #401), 루헤리·캐시 동시 선발 경기 평균 위치(#276), 마첸 전진 시 좌CB 히트맵 측면 열(열0~1) 수비 행동 비중(#290), 할 일 20(C2/C6) 판정 시 obs#443 vs obs#95 중 지지 방향(#46).','player_starts',3,'official',2,'RB',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(14,'AVL','알리송 측면 기용: 수비 복귀형 vs 윙어','알리송의 측면 역할을 wm_widemid(수비 복귀형)와 wm_winger 중 무엇으로 둘지 판정한다.','알리송 선발 경기의 태클·인터셉트·자기 진영 터치·히트맵(#316·#325), 우측 기용 시 상대 좌측(풀백 사이) 봉쇄 — 상대 좌측 터치·크로스 수(#299). 뉴캐슬전(45분)은 즉시 대조 가능하나 역할 판정은 3선발.','player_starts',3,'official',59,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(15,'AVL','비보유 기본 형태: 4-4-2 vs 4-4-1-1','빌라의 비보유 기본 형태가 4-4-2(CAM이 ST 높이)인지 4-4-1-1인지, 그 전환이 FC 구현 대상인지 판정한다.','PL 경기 반별 비보유 평균 위치(cells_def/map25_def)에서 잭슨−CAM 수비 액션 x 격차(0 근처=4-4-2, 15+=4-4-1-1, #426)가 3경기 이상 반복되는지(#463·#467·#472), 4-2-3-1↔4-4-2/4-3-3 전환(#378), 뉴캐슬전 비보유 블록 높이·PPDA(#320)와 72′ 교체 후 바클리·고레츠카 위치(#323). 이미 판정 가능.','matches',3,'league',NULL,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(16,'AVL','리드·수세 시 하강 형태: 편중 백5 vs 백6','리드 상황 후반 빌라의 하강 형태가 편중 백5인지 양 측면 하강 백6(또는 4-4-2 저블록)인지, 경기 프리셋/게임플랜 2안으로 옮길지 판정한다.','리드 국면(stats_json phase_lead>0)이 있었던 PL 경기만 본다. 후반 측면 미드 2명의 수비 평균 x가 백4 깊이까지 내려오는지 하프 분할(#366·#405·#201), 리드 시 2H 평균 높이 하강(#246), 토트넘전 상대 우측 전·후반 이벤트·박스 진입(#202), 뉴캐슬전 전·후반 점유율·패스 수·PPDA(#315). 2경기 이상이면 match_game_setups 반영 검토.','matches',2,'league',NULL,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(17,'AVL','압박 트리거: 1선→2선 패스 순간','빌라의 압박이 트리거 기반(상대 1선→2선 패스·CB 간 패스 직후)인지 확인하고 FC27 압박 트리거 설정으로 옮길지 판정한다.','선행 조건: FC27 압박 트리거 슬라이더의 게임 내 효과 실측(game_system_changes 행). 이후 PL 경기 이벤트에서 상대 CB 간 패스·1선→2선 패스 직후 빌라 미드 압박·탈취 비중(#253·#375), PPDA·높은 지역 탈취 수(#241·#321).','matches',5,'league',NULL,NULL,NULL,'2026-10-21',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(18,'AVL','카마라·고메스 동시 선발 시 배급 주도권(CB 1·2위)','카마라·고메스 동시 선발 경기에서 패스량 1·2위를 CB 듀오가 차지하는 패턴이 3회째 나오는지 판정한다(2026-10-11 사용자 결정).','고메스 선발 경기 중 카마라도 선발한 경기만. SofaScore pass_total 1·2위가 CB 듀오면 3회째 → APPLIED 후보로 사람 판단. ⚑ 10-17 뉴캐슬전(동시 선발)이 그 경기다 — pass_total 린델뢰프 57·스즈키 49·카마라 43·밍스 40 ⇒ 2위가 GK라 CB 듀오 1·2위 아님(3회째 미출현). 10-14 UCL은 고메스 미선발. #217(고메스 네트워크 허브)은 물량과 다른 축이라 같이 닫는다.','player_starts',1,'official',56,NULL,NULL,'2026-10-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(19,'AVL','카마라 RDM 역할: 홀딩 Defend vs DLP Build-Up','카마라 RDM 정본을 dm_holding/Defend로 유지할지 dm_dlp(Build-Up/Roaming)로 바꿀지 판정한다.','obs#1080 인게임 테스트 결론 + 카마라 RDM 선발 다음 PL 3경기의 단일 경기 커널 1위(#336·#456), 태클·인터셉트·리커버리(#329), 상대 3분의 1 국면 위치·전진 압박(#240), 고메스 짝 경기의 수비 행동/전진 패스 분담(#417).','player_starts',3,'league',12,'RDM',NULL,'2026-10-17',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(20,'AVL','더블 피벗 분업: 고메스 궂은일 vs 카마라 전진','카마라·고메스 짝의 공수 분업(누가 비우고 누가 받는지·누가 전진하는지)과 고메스 역할(cm_holding Ball-Winning vs dm 계열)을 판정한다.','고메스·카마라 동시 선발 경기의 국면 그리드(map25_poss/map25_def) 2경기 이상 비교(#270), 평균 위치·히트맵·태클·가로채기 분담(#279·#280), 고메스 전진 구역 비중·운반 지표(#285), 빌드업 수신 위치 분리 — WhoScored 이벤트(#268). 이미 판정 가능.','player_starts',3,'official',56,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(21,'AVL','2선(만잠비·부엔디아) 배치와 만잠비 역할','보유 시 2선이 4-2-2-2 박스(두 10번 안쪽)인지 4-4-1-1인지, 만잠비 CAM 역할·포커스(halfwinger Attack/Balanced vs classic10)를 판정한다.','만잠비 CAM 선발 3경기 이상에서 Attack이 Balanced를 fit Δ>0.05로 앞서는지(#200), 터치맵·전진 패스/드리블 비율로 classic10 판별(#301), 뉴캐슬전 전반 알리송·부엔디아·만잠비·잭슨 평균 위치·히트맵(하프스페이스 vs 측면, #311·#317·#322·#292), 페네르바체전 전반 좌우 반전 여부(#306), 부엔디아 CAM 히트맵 우측 편중(#204). 이미 판정 가능(만잠비 CAM 3선발).','player_starts',3,'official',55,'CAM',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(22,'AVL','밍스 선발 시 CB 역할: 빌드업 BPD vs 덜 관여하는 역할','밍스가 상대 압박의 표적·빌드업 약한 고리라는 서술을 근거로 밍스 선발 시 처방(cb_bpd/Aggressive)을 바꿀지 판정한다(사용자 판단).','밍스 선발 경기의 패스 성공률·전진 패스를 다른 CB와 대조, cb_defender/cb_stopper 적합도(#289), 브렌트퍼드전 9′ 장면 귀속(#210·#216·#234 — 4소스). 실측 정리 후 사용자 판단으로 넘긴다.','player_starts',3,'official',17,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(23,'AVL','토레스·린델뢰프 CB 포커스: Build-Up vs Aggressive','파우 토레스의 cb_bpd/Build-Up 적합도와 린델뢰프 RCB의 Build-Up 성향 혼재를 판정한다.','토레스 LCB 선발 경기의 전진 패스·압박 하 패스 성공률과 cb_bpd Build-Up fit(#275·#288), 린델뢰프 패스 출발 위치·상대 3분의 1 국면 위치 다경기 누적(#239 — 정본 RCB bpd Aggressive는 기하 1위).','player_starts',3,'official',4,'LCB',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(24,'AVL','하우드-벨리스 CB: 슬롯별 포커스와 공중볼','하우드-벨리스의 RCB/LCB 슬롯별 포커스(Build-Up vs Aggressive)와 공중볼 약점을 판정한다.','하우드-벨리스 선발 경기: RCB 선발 2경기 이상에서 전진 패스·롱볼 시도가 LCB 기용보다 많은지(#427·#442), 롱패스 시도·성공률(#278), 공중 듀얼 승률을 같은 슬롯 린델뢰프·토레스와 3경기 이상 대조(#443).','player_starts',3,'official',178,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(25,'AVL','고레츠카 기용 위치: 더블 피벗 vs 10번','고레츠카의 주 기용 위치를 판정해 처방(LDM dm_dlp/Roaming vs CAM cam_playmaker/Build-Up)과 대조한다.','고레츠카 첫 2경기 선발의 pos_label/pos_class·평균 좌표를 처방(LDM .807 · CAM .861)과 대조(#197·#447).','player_starts',2,'official',190,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(26,'AVL','헤밍스 LM 역할: 인사이드 포워드 vs 와이드 미드','헤밍스 LM 역할을 wm_insidefwd/Balanced로 유지할지 wm_widemid로 바꿀지 판정한다.','헤밍스 LM/LAM 선발 3경기 이상 단일 경기 fit에서 wm_insidefwd와 wm_widemid 차이가 0.05를 넘는지(#359·#432). 이미 판정 가능(LAM 6선발).','player_starts',3,'official',30,'LM,LAM',NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(27,'AVL','완비사카: 적응 추세와 좌측 기용 포커스','완비사카의 위치 이탈이 적응 추세로 줄어드는지, 좌측 기용 시 fb_fullback/Defend가 맞는지 판정한다.','완비사카 경기별 수비 지표·히트맵 추세(#287), LB 기용 경기(10-14·10-17)의 전진 패스·크로스·상대 진영 터치 대 태클·인터셉트로 fb_fullback Defend fit 확인(#293).','player_starts',3,'official',90,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(28,'AVL','아브라함 박스 움직임: 니어 침투 부재','아브라함이 니어포스트 침투 없이 파포스트에 머무는지(재현 한계 여부) 판정한다.','아브라함 공식전 선발 경기의 박스 안 터치 분포(니어/파, #205).','player_starts',3,'official',60,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(29,'AVL','세트피스 허용 억제와 득점 경로','세트피스 허용 자체를 줄이는 운용과 득점 경로(세트피스·하이프레스 전환)가 시즌 패턴인지 판정한다.','PL 경기별 허용 코너·박스 근처 프리킥 수·세트피스 실점(#274), 득점 경로 분포(세트피스·중원 탈취 전환 — #248, 게임플랜 서술로만 보관할지). 이미 판정 가능.','matches',5,'league',NULL,NULL,NULL,'2026-08-11',0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(30,'AVL','설정 축 없는 성향: 볼 처리 속도·크로스 빈도','「혼잡 지역 볼 처리 속도」「크로스를 적게 한다」를 FC 설정·PlayStyle로 옮길지, reproduction_limits로 등록할지 판정한다.','game_system_changes·docs/22에서 대응 축(PlayStyle·크로스 빈도 지시) 유무 확인(#54·#360), 있으면 PL 경기별 크로스 수가 리그 하위권인지 SofaScore 실측(#360). 없으면 reproduction_limits 등록 여부 결정. 문서 확인만 필요 — 즉시 판정 가능.','date',NULL,'official',NULL,NULL,'2026-10-21',NULL,0,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(31,'ATM','ATM 빌드업 스타일: Counter vs Short Passing','ATM team_tactic_setups의 비어 있는 빌드업 스타일을 Counter와 Short Passing 중 무엇으로 채울지 판정한다.','26/27 라리가 2경기 이상의 점유율·시퀀스당 패스·롱볼 비율·자기 진영 턴오버(#29·#63). 25/26 자료(#29)와 26/27 자료(#63)는 시즌을 섞지 않는다.','matches',2,'league',NULL,NULL,NULL,'2026-08-11',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(32,'ATM','ATM 포메이션 표기: 백3/백4/백5 유동 구조','ATM 포메이션 표기 충돌(4-4-2 / 3-4-2-1 / 5-3-2)이 요렌테 한 칸 높이·푸빌 위치에 따른 유동 구조인지 판정한다(HANDOFF 미해결 1).','더비 이후 공식전에서 우측 풀백의 비보유 셀 n≥15를 확보해 CB 라인과 같은 행인지(#183·#188), 요렌테 경기별 avg_x·pos_class 시계열(#76), 국면별 9번 교대의 2소스 교차(#3 — reproduction_limits 후보).','matches',1,'official',NULL,NULL,NULL,'2026-09-20',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(33,'ATM','요렌테 역할: RB vs 전진(RM·윙백)','요렌테를 RB(#476 정본)로 둘지 RM/윙백(fb_att_wb·wm_*)으로 옮길지 판정한다.','요렌테 RM/RWB 선발 경기의 포지션-순수 집계 2경기 이상으로 재산출(#66·#67, 3-4-2-1 슬롯 체계 선행), 90분 전부 RB인 경기의 fb_* 축 확정(#185). 실측상 RM 선발은 09-09·09-13·09-20.','player_starts',2,'official',159,'RM,RAM,RW,RWB',NULL,'2026-09-05',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(34,'ATM','ATM 공격 표적 측면: 설계된 우측 과부하','더비의 우측 과부하(이강인·줄리아노·우측 풀백)가 ATM 기본 설계인지, 상대에 따라 표적 측면이 바뀌는지 판정한다.','더비 이후 퇴장 없는 라리가 경기에서 우측 3인 평균 tool_x 합 vs 좌측 3인(#179), 이강인 tool_x>70 유지 시 RST 슬롯+role_note(#184), 경기별 표적 측면 변화(알라베스전 좌측, #231), 우측 3~4인 동시 진입 빈도 — 패스 네트워크 재수집 필요(#186).','matches',3,'league',NULL,NULL,NULL,'2026-09-20',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(35,'ATM','더비 후속: 코케 선발 전환·전반 템포 파울','코케가 선발로 전환됐는지(벤치=교체 임팩트 판정 정정 여부)와 전반 파울로 템포를 끊는 패턴이 반복되는지 판정한다.','더비 포함 라리가 3경기: 더비 이후 2경기 중 코케 선발이 있으면 #181·#187 정정 — ⚑ 실측상 코케는 10-10 알라베스전 RAM 선발(정정 조건 충족), 1H 파울이 상대의 2배 이상 3경기 누적이면 manager_profiles defence에 「템포 차단 파울」(#189).','matches',3,'league',NULL,NULL,NULL,'2026-09-19',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(36,'ATM','더비 수비 서술: 좌표로 확인 불가 항목','쿠티·요렌테 충돌 장면과 「상대 윙어를 측면으로 몰기」를 현 수집 축으로 판정할 수 없으므로 영상 확인·신규 축 사전등록 여부를 정한다.','#180: 77′ 디오망데 장면 영상 확인(터치·충돌 로그 없음). #190: 상대 윙어 터치 측면 비율 축을 docs/60 양식으로 사전등록할지 결정. 경기 카운트로는 닫히지 않음.','date',NULL,'official',NULL,NULL,'2026-10-21',NULL,1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(37,'ATM','카르도소 좌측 피벗 커버','좌측 수비형 미드(카르도소)가 좌측 풀백 전진을 커버하는지 판정한다.','카르도소 선발 2경기 누적 map25_def 좌측 열(열0~1) 비중(#230).','player_starts',2,'official',168,NULL,NULL,'2026-10-09',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(38,'ATM','ATM 리드 시 라인 하강: 상대 강도별 조건부 실패','ATM 리드 국면의 라인 하강을 line_height에 반영할지, 상대 강도 조건을 붙일지 판정한다(AVL optimal:lead도 같은 점검).','리드 국면이 있었던 공식전만: 리드 전후 평균 라인·PPDA를 2경기 이상, 상대 강도(강팀 원정 vs 그 외)로 분리(#69).','matches',2,'official',NULL,NULL,NULL,'2026-09-10',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(39,'ATM','압박 형태(함정·오각형)의 재현 한계 등록','「타이밍 함정」(ATM)과 「오각형 압박 함정」(CHE 알론소)을 reproduction_limits 4번째 pressing 행으로 묶어 등록할지 판정한다.','reproduction_limits pressing 기존 3행과 대조해 「압박 형태」 행 신설 여부 결정(#30·#4). 등록 판단만 남음 — 즉시 판정 가능. ⚠ 출처 팀 ATM(#30)·CHE(#4) 혼재 — rationale에 팀·체제 명기(불변규칙 7).','date',NULL,'official',NULL,NULL,'2026-10-21',NULL,1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(40,'CHE','CHE 빌드업 스타일: Counter·Balanced·Short','알론소 체제 regime 2의 빌드업 스타일을 Counter·Balanced·Short Passing 중 무엇으로 둘지 판정한다.','공식전 2경기 이상의 점유율·패스량(#6 브라이턴전 146패스·점유 25.6%는 경기 전용으로 이미 반영 — 시즌 정본과 분리, #21).','matches',2,'official',NULL,NULL,NULL,'2026-08-11',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(41,'CHE','헨더슨·카이세도 피벗 짝 균형','헨더슨·카이세도 짝이 수비 균형을 만드는지 판정한다.','헨더슨 선발 경기 중 카이세도 동시 선발만: 3경기 누적 상대 오픈플레이 xG 비교(#221, obs#993). 실측상 동시 선발은 10-10·10-17.','player_starts',3,'official',210,NULL,NULL,'2026-10-09',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(42,'CHE','CHE 좌측면 교대: 윙백 오버랩·로저스 안쪽','차바리아 오버랩 시 로저스가 하프스페이스로 들어오는 좌측 교대가 반복되는지 판정한다.','차바리아 선발 경기 중 로저스 동시 선발만: 2경기에서 로저스 map25_poss 하프스페이스 비중(#223).','player_starts',2,'official',80,NULL,NULL,'2026-10-09',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(43,'LIV','LIV 빌드업 스타일: Counter vs Balanced','이라올라 체제 regime 3의 빌드업 스타일을 Balanced(projected)에서 Counter로 바꿀지 판정한다.','PL 공식전 표본 1건 더(점유·xG·박스 터치·시퀀스당 패스, #35), 부임 전 추측판(#24)은 보조.','matches',1,'league',NULL,NULL,NULL,'2026-09-11',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(44,'LIV','소보슬라이 슬롯 확정과 박스 도착 포커스','소보슬라이 슬롯(RDM vs CAM)을 확정한 뒤 포커스를 Attack(박스 도착 허용)으로 재산출할지 판정한다.','소보슬라이 RDM 선발 누적으로 슬롯 확정(할 일 24, obs#772) 후 포커스 재산출(#38). CAM 표본과 비교.','player_starts',3,'official',51,'RDM',NULL,'2026-08-11',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(45,'LIV','맥 알리스터 역할: 딥라잉 플레이메이커 재산출','맥 알리스터 #491(role·focus·fit NULL)을 같은 pos_class 2경기로 재산출하고 서사(딥라잉 6번)와 argmax를 대조한다.','클럽 공식전 같은 pos_class 2경기(대표팀 World Cup 제외) → 처방 재산출, 서사 2소스(#82·#87)와 argmax 대조. ⚑ 실측상 LDM 선발 3경기(09-04·09-20·10-11) — 조건 충족.','player_starts',2,'official',50,'LDM',NULL,'2026-08-11',1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
INSERT INTO claim_issues VALUES(46,'LIV','rest-defense의 재현 한계 등록','「점유 중 볼 뒤 형태(rest-defense)는 설정 축이 아니라 역할 조합의 창발 속성」을 reproduction_limits in_possession 신규 행으로 등록할지 판정한다(사용자 판단).','소스 4건(LIV 3·리즈 1) 확보 — 등록 여부 사용자 판단만 남음(#62·#83). ⚠ 출처 팀 CHE 영상(#62, 리즈 진단)·LIV(#83) 혼재 — rationale에 명기.','date',NULL,'official',NULL,NULL,'2026-10-21',NULL,1,'open',NULL,NULL,NULL,'scripts/claim_issues.py --load issues.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21');
